#!/usr/bin/env bash
#
# هل الفرقُ بين شجرتين وثائقُ تخطيطٍ فقط؟ — يُسأل حين تحرّك main أثناء اختبار طلب.
#
# ═══ لمَ ═══
#
# الإثباتُ يشترط أن يكون ما اختُبر هو ما يُنشر. فإن دُفع إلى main أثناء ساعة
# الاختبار سطرٌ في `AI_COMMAND_CENTER/BACKLOG.md` سقط الإثبات، وأُعيدت ساعةُ
# PostgreSQL كلُّها — لملفٍّ لا يقرؤه التطبيق ولا يُشغَّل. فيُسأل هنا: هل كلُّ
# ما اختلف من القائمة الضيّقة أدناه؟ إن نعم فالكودُ المنشور هو ما اختُبر بايتًا
# بايتًا. وإن خرج ملفٌّ واحدٌ عنها بقي السقوطُ كما كان.
#
# ═══ القائمة — ضيّقةٌ صريحة ═══
#
#   AI_COMMAND_CENTER/**   ملفّاتُ التخطيط
#   docs/**.md             وثائق
#   *.md                   في جذر المستودع وحده (README.md، CLAUDE.md، …)
#
# ولا غيرُها: لا yml ولا json ولا إعداد ولا ترحيل ولا اختبار ولا مصدر، ولا
# ‎.md داخل app/ أو resources/ أو storefront/ أو ‎.github/ — ما يُقرأ في وقت
# التشغيل أو يقود CI لا يُستثنى. والقائمةُ تُوسَّع بقرارٍ لا بنمطٍ عامّ.
#
# ═══ الاستعمال ═══
#
#   docs-only-change.sh <من> <إلى>     (بصمتان أو شجرتان يعرفهما git)
#
# الخروج: 0 — كلُّ ما اختلف وثائق (أو لا فرق).
#         1 — ملفٌّ واحدٌ على الأقلّ خارج القائمة؛ تُطبع أسماؤها.
#         2 — تعذّر الحساب؛ ويُعامَل معاملةَ 1: لا استثناءَ بلا يقين.
#
# والمحذوفُ والمنقولُ يُعدّان باسمَيهما (`--no-renames`): نقلُ ملفٍّ من app/ إلى
# docs/ حذفٌ من app/ — فيسقط.

set -uo pipefail

[ $# -eq 2 ] || { echo "usage: $0 <from> <to>" >&2; exit 2; }

# المسارُ وثيقةُ تخطيط؟ — مطابقةٌ نصّيّة لا glob على القرص
allowed() {
    case "$1" in
        AI_COMMAND_CENTER/*) return 0 ;;
        docs/*.md) return 0 ;;
        */*) return 1 ;;
        *.md) return 0 ;;
    esac
    return 1
}

# والأسماءُ مفصولةٌ بـNUL لا بسطر: اسمٌ فيه سطرٌ جديد لا يُقسَم اسمين
list=$(mktemp)
trap 'rm -f "$list"' EXIT
git diff --no-renames --name-only -z "$1" "$2" > "$list" \
    || { echo "تعذّر حساب الفرق بين $1 و$2" >&2; exit 2; }

blocked=()
while IFS= read -r -d '' path; do
    if allowed "$path"; then
        echo "  ✓ ${path}"
    else
        blocked+=("$path")
    fi
done < "$list"

if [ ${#blocked[@]} -gt 0 ]; then
    printf '  ✗ %s\n' "${blocked[@]}"
    exit 1
fi

exit 0
